use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let num = input.as_u64().unwrap() as i64;
    let count = num.count_ones();
    if count % 2 == 0 {
        Value::Number(serde_json::Number::from(0))
    } else {
        Value::Number(serde_json::Number::from(1))
    }
}
